    {
      "name": "Int.Matrix.exists_ne_zero_int_vec_norm_le",
      "module_name": "Mathlib.NumberTheory.SiegelsLemma",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : Fintype α] [inst_1 : Fintype β] (A : Matrix α β ℤ),\n  Fintype.card α < Fintype.card β →\n    0 < Fintype.card α →\n      ∃ t,\n        t ≠ 0 ∧\n          A.mulVec t = 0 ∧\n            ‖t‖ ≤ (↑(Fintype.card β) * max 1 ‖A‖) ^ (↑(Fintype.card α) / (↑(Fintype.card β) - ↑(Fintype.card α)))"
    },
    {
      "name": "Int.Matrix.exists_ne_zero_int_vec_norm_le'",
      "module_name": "Mathlib.NumberTheory.SiegelsLemma",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : Fintype α] [inst_1 : Fintype β] (A : Matrix α β ℤ),\n  Fintype.card α < Fintype.card β →\n    0 < Fintype.card α →\n      A ≠ 0 →\n        ∃ t,\n          t ≠ 0 ∧\n            A.mulVec t = 0 ∧\n              ‖t‖ ≤ (↑(Fintype.card β) * ‖A‖) ^ (↑(Fintype.card α) / (↑(Fintype.card β) - ↑(Fintype.card α)))"
    },
    {
      "name": "Int.zpow_pred_clog_lt_self",
      "module_name": "Mathlib.Data.Int.Log",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semifield R] [inst_1 : LinearOrder R] [IsStrictOrderedRing R] [inst_3 : FloorSemiring R]\n  {b : ℕ} {r : R}, 1 < b → 0 < r → ↑b ^ (Int.clog b r - 1) < r"
    },
    {
      "name": "ZLattice.abs_repr_lt_of_norm_lt",
      "module_name": "Mathlib.Algebra.Module.ZLattice.Summable",
      "kind": "theorem",
      "type": "∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] [inst_2 : FiniteDimensional ℝ E]\n  {L : Submodule ℤ E} [inst_3 : DiscreteTopology ↥L] {ι : Type u_3} (b : Module.Basis ι ℤ ↥L) (x : ↥L) (n : ℕ),\n  ‖x‖ < ZLattice.normBound b * ↑n → ∀ (i : ι), |(b.repr x) i| < ↑n"
    },
    {
      "name": "Behrend.roth_lower_bound",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {N : ℕ}, ↑N * Real.exp (-4 * √(Real.log ↑N)) ≤ ↑(rothNumberNat N)"
    }
  ]
